mapper.select:
select count(*)
from sys_chat_session cs,
sys_chat_message cm,
sys_chat_entity_session ces
where cs.id = ces.chat_session_id
and cs.id = cm.chat_session_id

    and cs.id in

        #{chatSessionId}


and cs.biz_id in

    #{bizId}


    and cs.target_user_id = #{params.userId}

and cm.id > ces.last_read_message_id
and case when ces.clear_at is not null then cm.created_at > ces.clear_at else true end
and cs.biz_type = #{params.bizType}
and ces.user_id = #{params.userId}
and ces.clear_ind = 0

select count(*)
from sys_chat_session cs,
sys_chat_message cm
where cs.id = cm.chat_session_id
and cm.chat_session_id = cs.id

    and cs.id in

        #{chatSessionId}


and cs.biz_type = #{params.bizType}
and cs.biz_id in

    #{bizId}


    and cs.target_user_id = #{params.userId}

and not exists(select ces.id
from sys_chat_entity_session ces
where ces.chat_session_id = cs.id
and ces.user_id = #{params.userId})

select cm.chat_session_id as id, max(cm.id) as number from sys_chat_message cm where cm.active = 1 and cm.chat_session_id in
#{chatSessionId}
group by cm.chat_session_id

select scm.sender_user_id as id, max(scm.created_at) as dateTime from sys_chat_message scm where scm.active = 1 and scm.sender_user_id in
#{userId}
group by scm.sender_user_id
